INSERT OR REPLACE INTO timeline_eras (id, label, date_label, description, start_year, end_year, sort_order) VALUES ('era1_panghor','Ere I — Panghor (supercontinent)','Temps Primordiaux -> ~45 000 av.A','Un seul supercontinent entourant l''Ocean Premier. Les Eternels et les 12 Cosmiques faconne le monde. Les 45 Etheres s''installent dans leurs zones d''influence.',-999999,-45000,0);
INSERT OR REPLACE INTO timeline_eras (id, label, date_label, description, start_year, end_year, sort_order) VALUES ('era1_fracture1','Ere I — Fracture 1 : Grand Schisme','Temps Primordiaux -> Temps Primordiaux','Panghor se fend en deux masses — Panghor-Ven (Nord) et Panghor-Dra (Sud). L''Ocean Primordial s''ouvre entre elles. Baelor, Nysaria, Ulinor emergent comme fragments isoles de la chaine volcanique centrale.',-999999,-800000,1);
INSERT OR REPLACE INTO timeline_eras (id, label, date_label, description, start_year, end_year, sort_order) VALUES ('era1_fracture2','Ere I — Fracture 2 : L''Eclatement','Temps Primordiaux -> Temps Primordiaux','Panghor Nord et Sud se divisent en masses individuelles. Les futurs 13 continents prennent forme sur ~3 millions d''annees.',-600000,-100000,2);
INSERT OR REPLACE INTO timeline_eras (id, label, date_label, description, start_year, end_year, sort_order) VALUES ('era1_fracture3','Ere I — Fracture 3 : Les Details','Temps Primordiaux -> ~45 000 av.A','Cendara se separe d''Evertia (eruptions volcaniques). Cestra s''exile vers le nord (Mont Jumeau recouvert par Glacien). Azoria se fragmente en archipel. Les 13 continents sont stables — l''Ere des Mortels peut commencer.',-100000,-45000,3);
INSERT OR REPLACE INTO timeline_eras (id, label, date_label, description, start_year, end_year, sort_order) VALUES ('era2_berceaux','Ere II — Berceaux (~45 000 → ~30 000 av.A)','~45 000 av.A -> ~30 000 av.A','Les 5 Berceaux naissent. Premiers peuples : Marcheurs de Cendre (proto-kalvar), Enfants de la Roche (alkrath), Coureurs (proto-galennoth), Voix-sous-Bois (sylveth), Gens de l''Eau (aquen). Les 5 proto-civilisations ne se connaissent pas et se croient seules au monde.',-45000,-30000,4);
INSERT OR REPLACE INTO timeline_eras (id, label, date_label, description, start_year, end_year, sort_order) VALUES ('era2_gel_reconstruction','Ere II — Grand Gel et Reconstruction (~30 000 → ~20 000 av.A)','~30 000 av.A -> ~20 000 av.A','Grand Gel (~30 000 av.A, Climata) elimine 73% de la population mondiale. Reconstruction (~25 000 → ~20 000 av.A) : melange des peuples, cultures hybrides (Forgeurs-de-Roche, Cavaliers-des-Lizieres, Navigateurs-de-Sable...). Pose les bases de l''Ere III.',-30000,-20000,5);
INSERT OR REPLACE INTO timeline_eras (id, label, date_label, description, start_year, end_year, sort_order) VALUES ('era3_lien_empires','Ere III — Age du Lien (~20 000 → An 0)','~20 000 av.A -> ~0 ap.A','Trois individus decouvrent le Lien independamment (~20 000 av.A) : Orvane la Tisseuse (Celethor), Khatun Pyrecour (Cendara), Ildaran l''Ecouteur (Alkaran). 7 grands empires sur 20 000 ans. Age d''or : 6 empires simultanes, 7 cites volantes, 200+ portails, 120 millions d''habitants.',-20000,0,6);
INSERT OR REPLACE INTO timeline_eras (id, label, date_label, description, start_year, end_year, sort_order) VALUES ('era5_grande_nuit','Ere V — Grande Nuit (An 0 → ~3 000 ap.A)','~0 ap.A -> ~3 000 ap.A','3 000 ans de chaos. Empires effondrés. Trois royaumes intermediaires : Tharnok (Alkaran, forteresse de pierre), Forgon (Onara/Azoria, puissance maritime), Drahk''Nor (Ilthara/Endora, armee sans Lien). Fleau des Failles (~1 500 ap.A) elimine 40% des survivants. Population : 120M (An 0) → 90M → 18M (~3 000 ap.A).',0,3000,7);
INSERT OR REPLACE INTO timeline_eras (id, label, date_label, description, start_year, end_year, sort_order) VALUES ('era6_nations','Ere VI — Nations (~3 000 → ~9 500 ap.A)','~3 000 ap.A -> ~9 500 ap.A','38+ nations emergent depuis les royaumes intermediaires. 7 guerres majeures faconnent les frontieres. Guildes transnationales, systemes monetaires, routes commerciales. La Cristallisation (~8 000 → ~9 500) stabilise les frontieres. Traite des Treize Continents (~9 500 ap.A, 64 signataires) cloture l''ere.',3000,9500,8);
INSERT OR REPLACE INTO timeline_eras (id, label, date_label, description, start_year, end_year, sort_order) VALUES ('era7_actuelle','Ere VII — Actuelle (~9 500 → ~10 200 ap.A)','~9 500 ap.A -> ~10 200 ap.A','Paix fragile sous le Traite des Treize Continents (700 ans sans guerre inter-etatique majeure). Clivage Lies/Delies (~30% Lies). Catena Fracta. Guerre de l''Ombre (~9 850 → present). Quatre mysteres actifs : Coeur de Cendra (pulse), Silence des Phenix, Message de Mirathi (~10 064), Faille d''Ordavan (~10 142).',9500,10200,9);
